(()=>{const api=(window.API_BASE_URL||'').replace(/\/$/,'');const t=x=>I18N.t(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function request(route,options={}){const r=await fetch(api+route,{...options,headers:{'Accept-Language':I18N.lang,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const d=await r.json();if(!r.ok)throw Error(t(d.error||'تعذّر تنفيذ الطلب'));return d}const roles={reception:'الاستقبال والتسجيل',bibs:'تسليم الأرقام',route:'إرشاد المسار',water:'محطات المياه',finish:'خط النهاية',medical:'طاقم الإسعاف المؤهّل'};function status(message,error=false){const e=document.querySelector('#featureStatus');if(e){e.textContent=t(message);e.className=error?'error':'success'}}async function races(){let connected=false,events=RACE_EVENTS;try{const h=await request('/api/health');if(h.app==='khotwa'){events=await request('/api/events');connected=true}}catch{}return {connected,events:events.filter(e=>new Date(e.start)>new Date())}}function image(url,type='road'){return url?.startsWith('/uploads/')?api+url:url?.startsWith('assets/')?url:({trail:'assets/community-1.jpg',family:'assets/community-2.jpg',road:'assets/community-1.jpg'}[type]||'assets/community-1.jpg')}function duration(s){return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0')).join(':')}window.F={api,t,esc,request,roles,status,races,image,duration};})();
